// TypeScript Version: 4.1

import dlasq4 = require( './index' );

// TESTS //

// The function returns a Float64Array...
{
	const Z = new Float64Array( [ 5, 0, 7, 0, 9, 0, 3, 0, 10, 0, 4.5, 0, 18, 0, 0, 0 ] );
	const out = new Float64Array( 3 );

	dlasq4( 0, 3, Z, 0, 3, 0.2, 0.15, 0.1, 0.8, 0.7, 0.6, out ); // $ExpectType Float64Array
}

// The compiler throws an error if the function is provided a first argument which is not a number...
{
	const Z = new Float64Array( 16 );
	const out = new Float64Array( 3 );

	dlasq4( '5', 3, Z, 0, 3, 0.2, 0.15, 0.1, 0.8, 0.7, 0.6, out ); // $ExpectError
	dlasq4( true, 3, Z, 0, 3, 0.2, 0.15, 0.1, 0.8, 0.7, 0.6, out ); // $ExpectError
	dlasq4( false, 3, Z, 0, 3, 0.2, 0.15, 0.1, 0.8, 0.7, 0.6, out ); // $ExpectError
	dlasq4( null, 3, Z, 0, 3, 0.2, 0.15, 0.1, 0.8, 0.7, 0.6, out ); // $ExpectError
	dlasq4( undefined, 3, Z, 0, 3, 0.2, 0.15, 0.1, 0.8, 0.7, 0.6, out ); // $ExpectError
	dlasq4( [], 3, Z, 0, 3, 0.2, 0.15, 0.1, 0.8, 0.7, 0.6, out ); // $ExpectError
	dlasq4( {}, 3, Z, 0, 3, 0.2, 0.15, 0.1, 0.8, 0.7, 0.6, out ); // $ExpectError
	dlasq4( ( x: number ): number => x, 3, Z, 0, 3, 0.2, 0.15, 0.1, 0.8, 0.7, 0.6, out ); // $ExpectError
}

